1	import { useState, useRef } from "react";
2	import { useParams, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { toast } from "sonner";
10	import {
11	  CheckCircle2,
12	  Upload,
13	  FileText,
14	  X,
15	  Loader2,
16	  ExternalLink,
17	  Briefcase,
18	} from "lucide-react";
19	
20	const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
21	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
22	const ALLOWED_MIME = [
23	  "application/pdf",
24	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
25	  "application/msword",
26	  "text/plain",
27	  "application/rtf",
28	  "text/rtf",
29	];
30	
31	function hasAllowedExtension(filename: string): boolean {
32	  const lower = filename.toLowerCase();
33	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
34	}
35	
36	interface JobInfo {
37	  id: string;
38	  title: string;
39	  status: string;
40	}
41	
42	export default function Apply() {
43	  const { jobId } = useParams<{ jobId: string }>();
44	  const fileInputRef = useRef<HTMLInputElement>(null);
45	
46	  const [name, setName] = useState("");
47	  const [email, setEmail] = useState("");
48	  const [phone, setPhone] = useState("");
49	  const [linkedinUrl, setLinkedinUrl] = useState("");
50	  const [resumeFile, setResumeFile] = useState<File | null>(null);
51	  const [dragOver, setDragOver] = useState(false);
52	  const [submitting, setSubmitting] = useState(false);
53	  const [submitted, setSubmitted] = useState(false);
54	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
55	
56	  // Fetch minimal job info — no auth required via RPC
57	  const {
58	    data: job,
59	    isLoading: jobLoading,
60	    error: jobError,
61	  } = useQuery<JobInfo | null>({
62	    queryKey: ["apply-job-info", jobId],
63	    queryFn: async () => {
64	      if (!jobId) return null;
65	      const { data, error } = await supabase.rpc("get_job_apply_info", {
66	        p_job_id: jobId,
67	      });
68	      if (error) throw new Error(error.message);
69	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
70	      const row = Array.isArray(data) ? data[0] : data;
71	      return row as JobInfo;
72	    },
73	    enabled: !!jobId,
74	    retry: 1,
75	    staleTime: 60_000,
76	  });
77	
78	  const handleFileSelect = (file: File) => {
79	    if (file.size > MAX_FILE_BYTES) {
80	      toast.error("File exceeds 10MB limit");
81	      return;
82	    }
83	    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
84	      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
85	      return;
86	    }
87	    setResumeFile(file);
88	    setFieldErrors((prev) => ({ ...prev, resume: "" }));
89	  };
90	
91	  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
92	    e.preventDefault();
93	    setDragOver(false);
94	    const file = e.dataTransfer.files[0];
95	    if (file) handleFileSelect(file);
96	  };
97	
98	  const validate = (): boolean => {
99	    const errors: Record<string, string> = {};
100	    if (!name.trim()) errors.name = "Name is required";
101	    if (!email.trim()) errors.email = "Email is required";
102	    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
103	      errors.email = "Enter a valid email address";
104	    setFieldErrors(errors);
105	    return Object.keys(errors).length === 0;
106	  };
107	
108	  const handleSubmit = async (e: React.FormEvent) => {
109	    e.preventDefault();
110	    if (!validate()) return;
111	    if (!jobId) {
112	      toast.error("Invalid application link");
113	      return;
114	    }
115	
116	    setSubmitting(true);
117	    try {
118	      const form = new FormData();
119	      form.append("job_id", jobId);
120	      form.append("name", name.trim());
121	      form.append("email", email.trim().toLowerCase());
122	      if (phone.trim()) form.append("phone", phone.trim());
123	      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
124	      if (resumeFile) form.append("resume", resumeFile);
125	
126	      const { data: sessionData } = await supabase.auth.getSession();
127	      const headers: Record<string, string> = {
128	        // Supabase project URL and anon key from env — required even for anon calls
129	        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
130	      };
131	      if (sessionData.session?.access_token) {
132	        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
133	      } else {
134	        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
135	      }
136	
137	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
138	      const res = await fetch(
139	        `${supabaseUrl}/functions/v1/submit-application`,
140	        {
141	          method: "POST",
142	          headers,
143	          body: form,
144	        }
145	      );
146	
147	      const json = await res.json();
148	      if (!res.ok) {
149	        throw new Error(json.error || "Failed to submit application");
150	      }
151	
152	      setSubmitted(true);
153	    } catch (err: unknown) {
154	      const message =
155	        err instanceof Error ? err.message : "Submission failed. Please try again.";
156	      toast.error(message);
157	    } finally {
158	      setSubmitting(false);
159	    }
160	  };
161	
162	  // ── Success screen ──────────────────────────────────────────────────────
163	  if (submitted) {
164	    return (
165	      <div className="min-h-screen bg-background flex flex-col">
166	        <ApplyHeader />
167	        <main className="flex-1 flex items-center justify-center px-4 py-16">
168	          <div className="w-full max-w-md text-center space-y-6">
169	            <div className="flex justify-center">
170	              <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
171	                <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
172	              </div>
173	            </div>
174	            <div className="space-y-2">
175	              <h1 className="text-2xl font-semibold tracking-tight">
176	                Application Submitted Successfully!
177	              </h1>
178	              <p className="text-sm text-muted-foreground leading-relaxed">
179	                Thank you! We will review your information and get in touch shortly.
180	              </p>
181	            </div>
182	            <Link
183	              to="/"
184	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
185	            >
186	              Back to Jobs
187	            </Link>
188	          </div>
189	        </main>
190	        <ApplyFooter />
191	      </div>
192	    );
193	  }
194	
195	  // ── Job not found ───────────────────────────────────────────────────────
196	  if (!jobLoading && (jobError || !job)) {
197	    return (
198	      <div className="min-h-screen bg-background flex flex-col">
199	        <ApplyHeader />
200	        <main className="flex-1 flex items-center justify-center px-4 py-16">
201	          <div className="w-full max-w-md text-center space-y-4">
202	            <div className="flex justify-center">
203	              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
204	                <Briefcase className="h-7 w-7 text-muted-foreground" />
205	              </div>
206	            </div>
207	            <h1 className="text-xl font-semibold">Job not found</h1>
208	            <p className="text-sm text-muted-foreground">
209	              This application link may have expired or the job no longer exists.
210	            </p>
211	            <Link
212	              to="/"
213	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
214	            >
215	              Back to Jobs
216	            </Link>
217	          </div>
218	        </main>
219	        <ApplyFooter />
220	      </div>
221	    );
222	  }
223	
224	  return (
225	    <div className="min-h-screen bg-background flex flex-col">
226	      <ApplyHeader />
227	
228	      <main className="flex-1 flex items-start justify-center px-4 py-10">
229	        <div className="w-full max-w-lg">
230	          {/* Job title */}
231	          <div className="mb-8 space-y-1">
232	            {jobLoading ? (
233	              <>
234	                <Skeleton className="h-7 w-64" />
235	                <Skeleton className="h-4 w-40 mt-2" />
236	              </>
237	            ) : (
238	              <>
239	                <h1 className="text-2xl font-semibold tracking-tight leading-tight">
240	                  {job?.title ?? "Apply for this position"}
241	                </h1>
242	                <p className="text-sm text-muted-foreground">
243	                  Fill in your details below to apply.
244	                </p>
245	              </>
246	            )}
247	          </div>
248	
249	          <form onSubmit={handleSubmit} noValidate className="space-y-5">
250	            {/* Name */}
251	            <div className="space-y-1.5">
252	              <Label htmlFor="apply-name">
253	                Full Name <span className="text-destructive">*</span>
254	              </Label>
255	              <Input
256	                id="apply-name"
257	                type="text"
258	                placeholder="Jane Smith"
259	                value={name}
260	                onChange={(e) => {
261	                  setName(e.target.value);
262	                  if (fieldErrors.name)
263	                    setFieldErrors((prev) => ({ ...prev, name: "" }));
264	                }}
265	                autoComplete="name"
266	                aria-invalid={!!fieldErrors.name}
267	                aria-describedby={fieldErrors.name ? "name-error" : undefined}
268	                disabled={submitting}
269	              />
270	              {fieldErrors.name && (
271	                <p id="name-error" className="text-xs text-destructive">
272	                  {fieldErrors.name}
273	                </p>
274	              )}
275	            </div>
276	
277	            {/* Email */}
278	            <div className="space-y-1.5">
279	              <Label htmlFor="apply-email">
280	                Email Address <span className="text-destructive">*</span>
281	              </Label>
282	              <Input
283	                id="apply-email"
284	                type="email"
285	                placeholder="jane@example.com"
286	                value={email}
287	                onChange={(e) => {
288	                  setEmail(e.target.value);
289	                  if (fieldErrors.email)
290	                    setFieldErrors((prev) => ({ ...prev, email: "" }));
291	                }}
292	                autoComplete="email"
293	                aria-invalid={!!fieldErrors.email}
294	                aria-describedby={fieldErrors.email ? "email-error" : undefined}
295	                disabled={submitting}
296	              />
297	              {fieldErrors.email && (
298	                <p id="email-error" className="text-xs text-destructive">
299	                  {fieldErrors.email}
300	                </p>
301	              )}
302	            </div>
303	
304	            {/* Phone */}
305	            <div className="space-y-1.5">
306	              <Label htmlFor="apply-phone">Phone Number</Label>
307	              <Input
308	                id="apply-phone"
309	                type="tel"
310	                placeholder="+1 555 000 0000"
311	                value={phone}
312	                onChange={(e) => setPhone(e.target.value)}
313	                autoComplete="tel"
314	                disabled={submitting}
315	              />
316	            </div>
317	
318	            {/* Resume Upload */}
319	            <div className="space-y-1.5">
320	              <Label>Resume / CV</Label>
321	              {resumeFile ? (
322	                <div className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 px-4 py-3">
323	                  <FileText className="h-5 w-5 text-primary shrink-0" />
324	                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
325	                  <button
326	                    type="button"
327	                    onClick={() => {
328	                      setResumeFile(null);
329	                      if (fileInputRef.current) fileInputRef.current.value = "";
330	                    }}
331	                    className="text-muted-foreground hover:text-destructive transition-colors"
332	                    aria-label="Remove resume"
333	                    disabled={submitting}
334	                  >
335	                    <X className="h-4 w-4" />
336	                  </button>
337	                </div>
338	              ) : (
339	                <div
340	                  role="button"
341	                  tabIndex={0}
342	                  aria-label="Upload resume — PDF, DOCX, DOC, RTF, or TXT, max 10MB"
343	                  onKeyDown={(e) => {
344	                    if (e.key === "Enter" || e.key === " ")
345	                      fileInputRef.current?.click();
346	                  }}
347	                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-200 flex flex-col items-center gap-2 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
348	                    dragOver
349	                      ? "border-primary bg-primary/5 scale-[1.01]"
350	                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
351	                  }`}
352	                  onDragOver={(e) => {
353	                    e.preventDefault();
354	                    setDragOver(true);
355	                  }}
356	                  onDragLeave={() => setDragOver(false)}
357	                  onDrop={handleDrop}
358	                  onClick={() => fileInputRef.current?.click()}
359	                >
360	                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center">
361	                    <Upload className="h-5 w-5 text-primary" />
362	                  </div>
363	                  <p className="text-sm font-medium text-foreground">
364	                    Drop your resume here or{" "}
365	                    <span className="text-primary">click to browse</span>
366	                  </p>
367	                  <p className="text-xs text-muted-foreground">
368	                    PDF, DOCX, DOC, RTF, TXT · Max 10MB
369	                  </p>
370	                  <input
371	                    ref={fileInputRef}
372	                    id="resume-input"
373	                    type="file"
374	                    className="hidden"
375	                    accept=".pdf,.docx,.doc,.rtf,.txt"
376	                    onChange={(e) => {
377	                      const file = e.target.files?.[0];
378	                      if (file) handleFileSelect(file);
379	                    }}
380	                    disabled={submitting}
381	                  />
382	                </div>
383	              )}
384	            </div>
385	
386	            {/* LinkedIn URL */}
387	            <div className="space-y-1.5">
388	              <Label htmlFor="apply-linkedin" className="flex items-center gap-1.5">
389	                LinkedIn Profile
390	                <span className="text-xs font-normal text-muted-foreground">
391	                  (optional)
392	                </span>
393	              </Label>
394	              <div className="relative">
395	                <Input
396	                  id="apply-linkedin"
397	                  type="url"
398	                  placeholder="https://linkedin.com/in/jane-smith"
399	                  value={linkedinUrl}
400	                  onChange={(e) => setLinkedinUrl(e.target.value)}
401	                  className="pr-9"
402	                  disabled={submitting}
403	                />
404	                <ExternalLink className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
405	              </div>
406	            </div>
407	
408	            {/* Submit */}
409	            <Button
410	              type="submit"
411	              className="w-full gap-2"
412	              size="lg"
413	              disabled={submitting}
414	            >
415	              {submitting ? (
416	                <>
417	                  <Loader2 className="h-4 w-4 animate-spin" />
418	                  Submitting…
419	                </>
420	              ) : (
421	                "Submit Application"
422	              )}
423	            </Button>
424	          </form>
425	        </div>
426	      </main>
427	
428	      <ApplyFooter />
429	    </div>
430	  );
431	}
432	
433	function ApplyHeader() {
434	  return (
435	    <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
436	      <div className="max-w-2xl mx-auto px-4 py-4 flex items-center gap-2">
437	        <Link
438	          to="/"
439	          className="flex items-center gap-2 text-sm font-semibold text-foreground hover:text-primary transition-colors"
440	        >
441	          <div className="w-6 h-6 rounded bg-primary flex items-center justify-center">
442	            <span className="text-[11px] font-bold text-primary-foreground">R</span>
443	          </div>
444	          Rankora
445	        </Link>
446	      </div>
447	    </header>
448	  );
449	}
450	
451	function ApplyFooter() {
452	  return (
453	    <footer className="py-6 text-center">
454	      <p className="text-xs text-muted-foreground">
455	        Powered by{" "}
456	        <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">
457	          Rankora
458	        </Link>
459	      </p>
460	    </footer>
461	  );
462	}
