51	    });
52	  }
53	
54	  try {
55	    // Use service role to bypass RLS for inserting application and uploading file.
56	    // RLS insert policy already allows public inserts — service role is used so we
57	    // can also write to storage without requiring auth from the candidate.
58	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
59	
60	    const contentType = req.headers.get("content-type") ?? "";
61	
62	    let jobId: string;
63	    let name: string;
64	    let email: string;
65	    let phone: string | null = null;
66	    let linkedinUrl: string | null = null;
