68	
69	    if (contentType.includes("multipart/form-data")) {
70	      const form = await req.formData();
71	      jobId = (form.get("job_id") as string | null)?.trim() ?? "";
72	      name = (form.get("name") as string | null)?.trim() ?? "";
73	      email = (form.get("email") as string | null)?.trim() ?? "";
74	      phone = (form.get("phone") as string | null)?.trim() || null;
75	      linkedinUrl = (form.get("linkedin_url") as string | null)?.trim() || null;
76	      const fileEntry = form.get("resume");
77	      if (fileEntry instanceof File && fileEntry.size > 0) {
78	        resumeFile = fileEntry;
79	      }
80	    } else {
81	      // Fallback: JSON body (no file upload)
82	      const body = await req.json();
83	      jobId = body.job_id?.trim() ?? "";
84	      name = body.name?.trim() ?? "";
85	      email = body.email?.trim() ?? "";
86	      phone = body.phone?.trim() || null;
87	      linkedinUrl = body.linkedin_url?.trim() || null;
88	    }
89	
90	    // ── Validation ────────────────────────────────────────────────────────
91	    const errors: string[] = [];
92	    if (!jobId) errors.push("job_id is required");
