104	      ) {
105	        errors.push("Resume must be a PDF, DOCX, DOC, RTF, or TXT file");
106	      }
107	    }
108	
109	    if (errors.length > 0) {
110	      return new Response(JSON.stringify({ error: errors.join(". ") }), {
111	        status: 400,
112	        headers: { ...corsHeaders, "Content-Type": "application/json" },
