114	    }
115	
116	    // ── Verify job exists ─────────────────────────────────────────────────
117	    const { data: job, error: jobError } = await supabase
118	      .from("jobs")
119	      .select("id, status")
120	      .eq("id", jobId)
121	      .single();
122	
123	    if (jobError || !job) {
124	      return new Response(
125	        JSON.stringify({ error: "Job not found or no longer accepting applications" }),
126	        {
127	          status: 404,
128	          headers: { ...corsHeaders, "Content-Type": "application/json" },
