131	    }
132	
133	    // Generate a stable applicant ID for storage path
134	    const applicantId = crypto.randomUUID();
135	
136	    // ── Upload resume to storage ───────────────────────────────────────────
137	    let resumePath: string | null = null;
138	    let resumeFilename: string | null = null;
139	
140	    if (resumeFile) {
141	      const safeFilename = sanitizeFilename(resumeFile.name);
142	      const storagePath = `applications/${jobId}/${applicantId}/${safeFilename}`;
143	      const fileBuffer = await resumeFile.arrayBuffer();
144	
145	      const { error: uploadError } = await supabase.storage
146	        .from("resumes")
147	        .upload(storagePath, fileBuffer, {
148	          contentType: resumeFile.type || "application/octet-stream",
149	          upsert: false,
150	        });
151	
152	      if (uploadError) {
